-- 목적: book_text 페이지 단위 본문 적재 (asb · 이 파일: 4of11)
-- 실행자: 팀장(Supabase SQL Editor). 워커 초안. 워커 DB 직접 쓰기 금지.
-- 근거 ADR: ADR-0056 (ADR-0056 D1·D2·D4·D5) · Accepted 2026-08-10
-- source 라벨: manifest_txt_v1
-- 이 파일 담당: 48권 / 508행 (정제 후 빈 면 0행 포함 — D7)
-- 생성기: scripts/tts_pilot/gen_book_text_sql_v2.py
-- 매핑: page_index = (P번호|json page) - 1 (0-based, D2/D11). blocks = NULL(원천에 블록 정보 없음).
-- 정제: tts_targets.sanitize() 공유(D6). 표지 행 없음(D3).
-- 인용: $$ 달러 인용. 생성 시 '$$' 포함·'$' 종결 전수 가드 통과.
-- 중복: ON CONFLICT (book_id, page_index) DO NOTHING — 기존 행을 덮어쓰지 않는다.
--
-- ★ 이 파일은 ROLLBACK; 으로 끝난다. [적재검증]까지 기대값과 일치하면
--   마지막 ROLLBACK; 을 COMMIT; 으로 직접 바꿔 타이핑해 확정한다.

-- ───────── [선검증] 트랜잭션 밖 ─────────
-- (a) 대상 권의 기존 book_text 행 수 — 기대 0. 0이 아니면 중단하고 보고할 것.
SELECT count(*) AS rows_before FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('22191', '22194', '22256', '22261', '22315', '22325', '22357', '22410', '22481', '22510', '22542', '22550', '22565', '22599', '22602', '22642', '22659', '22675', '22679', '22702', '22706', '22741', '22772', '2278', '22870', '22971', '22996', '23002', '23015', '23064', '23116', '23135', '23150', '23165', '23172', '23187', '23220', '2327', '23405', '23430', '23686', '23798', '23860', '23861', '23862', '23936', '23938', '23944');
-- (b) 대상 source_id 중 books에 존재하는 권 수 — 기대 48
SELECT count(*) AS books_found FROM books
  WHERE source_platform='african_storybook' AND source_id IN ('22191', '22194', '22256', '22261', '22315', '22325', '22357', '22410', '22481', '22510', '22542', '22550', '22565', '22599', '22602', '22642', '22659', '22675', '22679', '22702', '22706', '22741', '22772', '2278', '22870', '22971', '22996', '23002', '23015', '23064', '23116', '23135', '23150', '23165', '23172', '23187', '23220', '2327', '23405', '23430', '23686', '23798', '23860', '23861', '23862', '23936', '23938', '23944');

-- ───────── [적재] ─────────
BEGIN;
INSERT INTO book_text (book_id, page_index, text, blocks, source)
SELECT b.id, v.page_index, v.text, NULL::jsonb, $$manifest_txt_v1$$
  FROM (VALUES
    ('22191', 0, $$The drum has always been an important musical instrument in our community. We love drums!$$),
    ('22191', 1, $$We play drums using beaters, or with our fingers.$$),
    ('22191', 2, $$Drums enrich songs and make people want to dance. Drums make ceremonies colourful.$$),
    ('22191', 3, $$We sound drums to announce grief and call people when death occurs.$$),
    ('22191', 4, $$We sound drums to call people to clean wells, clear roads, or to build a hut for a needy old person.$$),
    ('22191', 5, $$We sound drums to gather people for meetings at our chief's palace.$$),
    ('22191', 6, $$Drums call people to go to church for prayers on Sundays, and other prayer days.$$),
    ('22191', 7, $$The big drum sounds, "An a bul mba, an a bul mba, an a bul mba-mba-mba-mba bul. "$$),
    ('22194', 0, $$Bul, Fumbo, Teke, Tongoli, Milege, Sos and Gwara were great friends. They also produced good music. They lived at the foot of faraway hills.$$),
    ('22194', 1, $$To be chosen as the greatest, the musician had to perform a variety of functions. He had to be loud enough to be heard from near and far.$$),
    ('22194', 2, $$"You are right Tongoli," Fumbo agreed. "But, you are not better than me. You are too soft. I am loud and clear. My sound reaches near and far. "$$),
    ('22194', 3, $$"You are both great," agreed Milege. Then he continued, "My work is simple. Dancers tie me round their ankles. They stamp their feet rhythmically and I produce melodies. I produce a mix of loud and sharp sounds. Friends, aren't I great? "$$),
    ('22194', 4, $$"That is great! " Bul said. "I am made of just a piece of skin stretched over a hollow wooden cylinder. I give rhythm to songs and my sound signals many things. But I cannot change pitches like some of you do. I don't think I am great. "$$),
    ('22194', 5, $$"Bul, you do great things! " Gwara disagreed. "You call people to meetings, worship, and communal work, also announce deaths and alert people when there is danger. You sound during ceremonies and make people dance in joy and sorrow. To me, you are the greatest. "$$),
    ('22194', 6, $$The skilful musicians looked at one another in disbelief and silence. Then Tongoli said, "Bul is too simple to be our king. I am the greatest because I can play from low to high with ease. "$$),
    ('22194', 7, $$Sos continued, "A person who cannot feel music produced by Bul is like dead wood! Bul draws people to him and nurtures them with his music in sorrow and in joy. "$$),
    ('22256', 0, $$Kate has a thing in her head.$$),
    ('22256', 1, $$It makes her tired.$$),
    ('22256', 2, $$She can't eat. She can't drink.$$),
    ('22256', 3, $$Oh dear. Poor woman! Her head throbs with pain.$$),
    ('22256', 4, $$The doctor sees a swelling in her head and says, "There is a tumour in your brain. "$$),
    ('22256', 5, $$"We have to remove it from your brain right now. We have to remove it now! " the doctor says.$$),
    ('22256', 6, $$They bring a stretcher.$$),
    ('22256', 7, $$They arrange the surgical blades.$$),
    ('22256', 8, $$They inject her with syringes.$$),
    ('22256', 9, $$They cut open Kate's head.$$),
    ('22256', 10, $$They remove the brain.$$),
    ('22256', 11, $$They cut out the tumour.$$),
    ('22256', 12, $$They return the brain to the skull.$$),
    ('22256', 13, $$Does Kate feel everything they do?$$),
    ('22256', 14, $$Then she comes back to life!$$),
    ('22256', 15, $$Now she is well. Like a new born baby.$$),
    ('22256', 16, $$We are all happy for our friend Kate, who tasted heaven.$$),
    ('22261', 0, $$There lived an old man called Hagos. He lived with his three sons.$$),
    ('22261', 1, $$Hagos went to his neighbour Haile and said, "I want my sons to have wealth. I have prepared three boxes. I want you to give them the boxes after I die. "$$),
    ('22261', 2, $$After Hagos died, Haile called the sons together.$$),
    ('22261', 3, $$The sons took the boxes and opened them.$$),
    ('22261', 4, $$The one who found gold was very happy. The other two were not happy. They started quarrelling with him.$$),
    ('22261', 5, $$"You are brothers, you should not quarrel. Let me take you to a wise old man to advise you," said Haile to the three brothers.$$),
    ('22261', 6, $$Haile took the brothers to the wise old man.$$),
    ('22261', 7, $$Haile told the wise old man about the three boxes that Hagos had left for his sons.$$),
    ('22261', 8, $$The wise old man asserted, "Your father had a reason for giving each of you a particular box. "$$),
    ('22261', 9, $$He continued, "The one who received gold, your father wants you to be a merchant. The one who received soil, your father wants you to be a farmer. "$$),
    ('22261', 10, $$"The one who received animal dung, your father wants you to be a cowboy. Your father wanted you each to have his own profession," the old man concluded.$$),
    ('22261', 11, $$After they listened to the old man's advice the three brothers agreed. They worked in their professions and lived happily.$$),
    ('22315', 0, $$Coffee is a plant which has fruit. The fruit are berries.$$),
    ('22315', 1, $$There are legends about the discovery of coffee. One of them is the legend of Kaldi in Ethiopia.$$),
    ('22315', 2, $$Kaldi was a young Ethiopian shepherd.$$),
    ('22315', 3, $$One day his goats ate red berries off the coffee plant and Kaldi noticed that they started jumping around.$$),
    ('22315', 4, $$Kaldi was eager to know whether the berries gave the goats energy. He chewed the fruit. The taste was extremely bitter!$$),
    ('22315', 5, $$After a while, Kaldi felt alert and full of energy.$$),
    ('22315', 6, $$He picked some of the coffee fruit and took it home.$$),
    ('22315', 7, $$He gave some fruit to his wife.$$),
    ('22315', 8, $$His wife chewed the berries and felt the same effects that Kaldi had felt.$$),
    ('22315', 9, $$Kaldi and his wife thought that it was a gift from God.$$),
    ('22315', 10, $$Days later, Kaldi took some of the fruit and leaves of the coffee plant to a nearby monastery.$$),
    ('22315', 11, $$Kaldi told the whole story to the monks, and then left the monastery.$$),
    ('22315', 12, $$The monks secretly followed Kaldi to check whether what he had told them was true.$$),
    ('22315', 13, $$The monks saw that everything Kaldi told them was true. The goats were in a playful mood.$$),
    ('22315', 14, $$Back at monastery, the monks told the other monks to boil the coffee fruit.$$),
    ('22315', 15, $$The monks drank the boiled fruit and found it terribly bitter!$$),
    ('22315', 16, $$They threw the remains of the fruit onto a fire. Suddenly, a nice aroma came from the fire.$$),
    ('22315', 17, $$A noble idea of roasting, then boiling the seeds came to their minds.$$),
    ('22315', 18, $$After they had drunk this flavourful beverage, they stayed alert and felt energetic.$$),
    ('22315', 19, $$Since then, people have drunk brewed coffee to stay awake.$$),
    ('22315', 20, $$Coffee drinking started in Ethiopia and spread across the world!$$),
    ('22325', 0, $$Musa lives with his parents in the village of Kagadama, in Nigeria.$$),
    ('22325', 1, $$Musa is also a bully. He always beats his friends.$$),
    ('22325', 2, $$One day on his way back from school, he sees a cat.$$),
    ('22325', 3, $$When his father sees him, he says "Musa stop abusing that cat! Take it back to where you found it. "$$),
    ('22325', 4, $$Musa refuses to return the cat and locks it in a cage.$$),
    ('22325', 5, $$As he is sleeping in his room that night, Musa has a dream.$$),
    ('22325', 6, $$The cat starts to swallow his feet. It eats half way up to Musa's knees.$$),
    ('22325', 7, $$The next day Musa returns the cat to where he found it.$$),
    ('22357', 0, $$Gemo and Nelson were brothers.$$),
    ('22357', 1, $$Gemo went to school every day, but Nelson did not.$$),
    ('22357', 2, $$Their father went to work in the town.$$),
    ('22357', 3, $$One day his father left some money on the table.$$),
    ('22357', 4, $$His father was very angry.$$),
    ('22357', 5, $$So Nelson ran away.$$),
    ('22357', 6, $$He sat under a tree all night.$$),
    ('22357', 7, $$His brother Gemo found him under the tree, and took him home.$$),
    ('22357', 8, $$"Why did you steal the money? " asked his father.$$),
    ('22357', 9, $$"Why did you run away? " asked his mother.$$),
    ('22357', 10, $$"I am very, very sorry," said Nelson, and he returned the money.$$),
    ('22357', 11, $$They hugged him and were happy again.$$),
