    ('23150', 0, $$There once was a flower that grew as tall as a tree.$$),
    ('23150', 1, $$The flower's petals were so big.$$),
    ('23150', 2, $$... and dresses.$$),
    ('23150', 3, $$And houses...$$),
    ('23150', 4, $$Someone came up with a solution, so that there could be more & more flowers$$),
